/// <summary>
/// 126687 2nd API to communicate during submission / validation / posting of the journal
/// </summary>
[DataContractAttribute]
class MET_CheckJournalPostStatusResponse
{
    private boolean     success;
    private str         errorMessage;
    private str         debugMessage;
    private str         workflowStatus;
    private str         JournalNum;

}

Method.Source:
    [DataMember("JournalNum")]
    public str parmJournalNum(str _value = JournalNum)
    {
        if (!prmIsDefault(_value))
        {
            JournalNum = _value;
        }

        return JournalNum;
    }

