    }

    [DataMember("Success")]
    public Boolean parmSuccess(Boolean _value = success)
    {
        if (!prmIsDefault(_value))
        {
            success = _value;
        }

        return success;
    }

    [DataMember("WorkflowStatus")]
    public str parmWorkflowStatus(str _value = WorkflowStatus)
    {
        if (!prmIsDefault(_value))
        {
